import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type StockMarketBarsProps = Record<string, any>;

const StockMarketBars: React.FC<StockMarketBarsProps> = ({
  backgroundColor = "#0f172a", // slate-900
  transparentBackground = false,
  durationInSeconds = 10,
  barColorStatic = "#3b82f6", // blue-500
  barColorFluctuating = "#10b981", // emerald-500
  labelTextStatic = "Assets",
  labelTextFluctuating = "Assets",
  fluctuationVolatility = 6,
  baseBarHeightPercentage = 0.5,
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Space Grotesk"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Dashboard background grid pattern
  const gridBackground = transparentBackground 
    ? "none" 
    : `linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px)`;
  const gridSize = `${width * 0.05}px ${width * 0.05}px`;

  // Entrance spring animation
  const entrance = spring({
    fps,
    frame,
    config: { damping: 14, mass: 0.8 },
  });

  const labelFade = interpolate(frame, [10, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Chart layout dimensions
  const floorPadding = height * 0.15;
  const chartHeight = height * 0.65;
  const barWidth = width * 0.12;

  // --- Static Bar Logic ---
  const staticHeightTarget = chartHeight * baseBarHeightPercentage;
  const staticHeight = Math.max(0, staticHeightTarget * entrance);

  // --- Fluctuating Bar Logic ---
  // Determine how many frames between each random jump
  const tickDuration = Math.max(5, Math.floor(40 - fluctuationVolatility * 3));
  const currentTick = Math.floor(frame / tickDuration);
  const tickProgress = Easing.inOut(Easing.ease)((frame % tickDuration) / tickDuration);

  // Generate pseudo-random targets for smooth interpolation
  const val1 = random(`fluc-${currentTick}`);
  const val2 = random(`fluc-${currentTick + 1}`);

  // Fluctuation bounds based on overall chart height
  const minFluc = chartHeight * 0.2;
  const maxFluc = chartHeight * 1.0;

  const p1Height = interpolate(val1, [0, 1], [minFluc, maxFluc]);
  const p2Height = interpolate(val2, [0, 1], [minFluc, maxFluc]);

  // Interpolate between the two random targets
  const targetFlucHeight = interpolate(tickProgress, [0, 1], [p1Height, p2Height]);
  
  // Apply initial entrance animation to the fluctuating value
  const fluctuatingHeight = Math.max(0, targetFlucHeight * entrance);

  // --- Dynamic Text Values ---
  // Map pixel height to a mock "dollar value" (e.g., full height = 200k)
  const staticValue = Math.round(interpolate(staticHeight, [0, chartHeight], [0, 200]));
  const flucValue = Math.round(interpolate(fluctuatingHeight, [0, chartHeight], [0, 200]));

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        backgroundImage: gridBackground,
        backgroundSize: gridSize,
        fontFamily: "Space Grotesk", 
        color: "white" 
      }}
    >
      {/* Background Axis Lines */}
      <div 
        style={{ 
          position: "absolute", 
          bottom: floorPadding, 
          left: "10%", 
          right: "10%", 
          height: chartHeight 
        }}
      >
        {[0, 0.25, 0.5, 0.75, 1].map((pct, i) => (
          <div
            key={i}
            style={{
              position: "absolute",
              bottom: `${pct * 100}%`,
              width: "100%",
              borderBottom: `2px dashed rgba(255, 255, 255, ${interpolate(entrance, [0, 1], [0, 0.08])})`,
              transition: "none",
            }}
          >
            <div 
              style={{
                position: "absolute",
                left: -70,
                bottom: -12,
                fontSize: height * 0.02,
                color: "rgba(255, 255, 255, 0.4)",
                opacity: labelFade,
                width: 50,
                textAlign: "right",
              }}
            >
              {Math.round(pct * 200)}k
            </div>
          </div>
        ))}
      </div>

      {/* Primary Bar Container */}
      <div
        style={{
          position: "absolute",
          bottom: floorPadding,
          width: "100%",
          display: "flex",
          flexDirection: "row",
          justifyContent: "center",
          alignItems: "flex-end",
          gap: width * 0.15,
        }}
      >
        {/* Left: Static Bar */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
          <div
            style={{
              marginBottom: 15,
              fontSize: height * 0.035,
              fontWeight: 600,
              color: "rgba(255, 255, 255, 0.95)",
              opacity: labelFade,
              transform: `translateY(${interpolate(labelFade, [0, 1], [15, 0])}px)`,
            }}
          >
            ${staticValue}k
          </div>
          <div
            style={{
              width: barWidth,
              height: staticHeight,
              backgroundColor: barColorStatic,
              borderRadius: "16px 16px 0 0",
              boxShadow: `0 0 50px ${barColorStatic}30`,
              transition: "none",
            }}
          />
          <div
            style={{
              marginTop: 25,
              fontSize: height * 0.035,
              fontWeight: 700,
              opacity: labelFade,
              textTransform: "uppercase",
              letterSpacing: "0.06em",
              color: barColorStatic,
            }}
          >
            {labelTextStatic}
          </div>
          <div 
            style={{ 
              opacity: labelFade, 
              color: "rgba(255,255,255,0.4)", 
              fontSize: height * 0.02, 
              marginTop: 6,
              letterSpacing: "0.02em"
            }}
          >
            Fixed Value
          </div>
        </div>

        {/* Right: Fluctuating Bar */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
          <div
            style={{
              marginBottom: 15,
              fontSize: height * 0.035,
              fontWeight: 600,
              color: "rgba(255, 255, 255, 0.95)",
              opacity: labelFade,
              transform: `translateY(${interpolate(labelFade, [0, 1], [15, 0])}px)`,
            }}
          >
            ${flucValue}k
          </div>
          <div
            style={{
              width: barWidth,
              height: fluctuatingHeight,
              backgroundColor: barColorFluctuating,
              borderRadius: "16px 16px 0 0",
              boxShadow: `0 0 50px ${barColorFluctuating}30`,
              transition: "none",
            }}
          />
          <div
            style={{
              marginTop: 25,
              fontSize: height * 0.035,
              fontWeight: 700,
              opacity: labelFade,
              textTransform: "uppercase",
              letterSpacing: "0.06em",
              color: barColorFluctuating,
            }}
          >
            {labelTextFluctuating}
          </div>
          <div 
            style={{ 
              opacity: labelFade, 
              color: "rgba(255,255,255,0.4)", 
              fontSize: height * 0.02, 
              marginTop: 6,
              letterSpacing: "0.02em"
            }}
          >
            Market Value
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default StockMarketBars;